/** Real results from the first mcp-evals run (2026-10-16), generated by scripts/build-eval-matrix.mjs. */
import data from "../generated/eval-matrix.json";

export type Outcome = "pass" | "fail" | "error";

export interface RepeatResult {
  outcome: Outcome;
  end: string;
  steps: number;
  contextTokens: number;
  costUsd: number;
  latencyMs: number;
}

export interface Column {
  server: string;
  model: string;
  /** Full label, e.g. "NeatCode · GPT-6.1 Sol". */
  label: string;
  /** Two-line short header for narrow screens. */
  short: [string, string];
}

export interface CellResult {
  task: string;
  column: number;
  repeats: RepeatResult[];
  passes: number;
}

const SERVER_LABEL: Record<string, [string, string]> = {
  neatcode: ["NeatCode", "NC"],
  filesystem: ["Filesystem", "FS"],
};
const MODEL_LABEL: Record<string, [string, string]> = {
  "openai/gpt-6.1-sol": ["GPT-6.1 Sol", "GPT"],
  "google/gemini-3.8-flash": ["Gemini 3.8 Flash", "Gem"],
  "qwen/qwen3.8-flash": ["Qwen3.8 Flash", "Qwen"],
};

const columns: Column[] = data.servers.flatMap((server) =>
  data.models.map((model) => {
    const [s, sShort] = SERVER_LABEL[server] ?? [server, server];
    const [m, mShort] = MODEL_LABEL[model] ?? [model, model];
    return { server, model, label: `${s} · ${m}`, short: [sShort, mShort] as [string, string] };
  }),
);

export const evalRun = {
  label: "First mcp-evals run, 2026-10-16",
  runId: data.runId,
  tasks: data.tasks,
  columns,
  results: data.tasks.flatMap((task) =>
    columns.map((col, c): CellResult => {
      const repeats = data.runs
        .filter((r) => r.task === task && r.server === col.server && r.model === col.model)
        .sort((a, b) => a.repeat - b.repeat)
        .map(({ outcome, end, steps, contextTokens, costUsd, latencyMs }) => ({
          outcome: outcome as Outcome,
          end,
          steps,
          contextTokens,
          costUsd,
          latencyMs,
        }));
      return { task, column: c, repeats, passes: repeats.filter((r) => r.outcome === "pass").length };
    }),
  ),
};

/** Plain-words reason a repeat ended. */
export function describeEnd(r: RepeatResult): string {
  switch (r.end) {
    case "final_answer":
      return r.outcome === "pass" ? "gave a correct final answer" : "gave a final answer that failed a check";
    case "max_steps":
      return "hit the 12-step limit";
    case "timeout":
      return "timed out at 180 s";
    case "invalid_tool_call":
      return "called a tool that doesn't exist";
    default:
      return r.end.replaceAll("_", " ");
  }
}

/** Order in which cells fill during replay: column by column, like models finishing tasks. */
export function replayOrder(run: typeof evalRun): number[] {
  const order: number[] = [];
  for (let c = 0; c < run.columns.length; c++)
    for (let t = 0; t < run.tasks.length; t++) order.push(t * run.columns.length + c);
  return order;
}
